export function mountCredit(type){const r=recordings[type],container=document.querySelector('.sound-controls'),note=document.createElement('span');note.className='audio-kind';note.textContent=r?'הקלטת שטח · קטע קצר בלולאה':'צליל מסונתז · המחשה';container.append(note);if(!r)return;
 const b=document.createElement('button');b.className='audio-credit';b.textContent='מקור ההקלטה ורישיון';b.type='button';container.append(b);const d=document.createElement('dialog');d.setAttribute('aria-labelledby','audio-credit-title');d.innerHTML=`<button class="close" aria-label="סגירה">×</button><h2 id="audio-credit-title">מקור ההקלטה ורישיון</h2><p lang="en" dir="ltr">${r.title}</p><p>מקליט: <b dir="auto">${r.author}</b></p><p>${r.description}</p>${r.nonCommercial?'<p><b>לשימוש לא־מסחרי בלבד.</b> יש לתת קרדיט למקליט. ההגבלה חלה גם על הקטע הערוך להורדה.</p>':''}<p>עריכה ביישום: קיצור קטע שמתחיל בשנייה ${r.start}, איזון עוצמה, דחיסת MP3 ומעבר מוצלב לחזרה בלולאה. ללא שינוי מהירות ההקלטה. משך הקטע: כ־22 שניות.</p><p><a href="${r.source}" target="_blank" rel="noopener">ההקלטה המקורית ↗</a> · <a href="${r.licenseUrl}" target="_blank" rel="noopener">${r.license} ↗</a></p><p>הקטע הערוך מופץ ברישיון ${r.license}. הקרדיט אינו מעיד על תמיכת המקליט ביישום.</p><a class="button" href="/assets/audio/${r.file}.mp3" target="_blank" download>הורדת הקטע הערוך</a>`;document.body.append(d);b.onclick=()=>d.showModal();d.querySelector('button').onclick=()=>d.close();d.onclick=e=>{if(e.target===d)d.close();};return()=>{d.close();d.remove();};}
export function createRecordedAudio(type){const info=recordings[type],button=document.getElementById('sound-toggle'),volume=document.getElementById('sound-volume'),label=document.getElementById('sound-status');let ctx,gain,source,buffer,loading=false,enabled=false,paused=false,visible=true,disposed=false,intensity=.5,error='';const abort=new AbortController();
 function sync(){if(disposed)return;const audible=enabled&&!paused&&!document.hidden;if(gain)gain.gain.setTargetAtTime(audible?Number(volume.value)/100*(.65+intensity*.35):0,ctx.currentTime,.08);button.textContent=loading?'טעינת ההקלטה…':enabled?'השתקת הקול':'הפעלת ההקלטה';button.disabled=loading;button.setAttribute('aria-pressed',String(enabled));label.textContent=error||(loading?'ההקלטה נטענת':enabled?(paused?'הקול מושהה עם הסופה':'הקלטת שטח מתנגנת'):'הקול כבוי');}
 button.onclick=async()=>{if(disposed||loading)return;error='';try{if(!ctx){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)throw Error('No audio');ctx=new AC();gain=ctx.createGain();gain.gain.value=0;gain.connect(ctx.destination);}const resume=ctx.resume();enabled=!enabled;sync();await resume;if(disposed)return;if(enabled&&!buffer){loading=true;sync();const res=await fetch('/assets/audio/'+info.file+'.mp3',{signal:abort.signal});if(!res.ok)throw Error('Download');buffer=await ctx.decodeAudioData(await res.arrayBuffer());if(disposed)return;source=ctx.createBufferSource();source.buffer=buffer;source.loop=true;source.connect(gain);source.start();}loading=false;sync();}catch(e){if(disposed)return;loading=false;enabled=false;error='לא ניתן לטעון את ההקלטה כרגע. התחברו לאינטרנט ונסו שוב.';sync();}};
 volume.oninput=()=>{document.getElementById('sound-volume-value').value=volume.value+'%';sync();};document.addEventListener('visibilitychange',sync);sync();return {update(p,i,v=true){paused=p;intensity=i;visible=v;sync();},destroy(){disposed=true;abort.abort();document.removeEventListener('visibilitychange',sync);if(source){source.stop();source.disconnect();}if(ctx&&ctx.state!=='closed')ctx.close().catch(()=>{});button.onclick=null;volume.oninput=null;}};
}
